import { defineTool as defineTool21 } from "npm:@lovable.dev/mcp-js@0.23.0";
import { z as z20 } from "npm:zod@^3.25.76";
var sendQuoteEmail_default = defineTool21({
  name: "sendQuoteEmail",
  title: "Email Mortgage Quote to Recipient (External Send)",
  description: "Use this ONLY when the user has explicitly asked to email a quote to a specific recipient and has approved sending. This is an external action that delivers real email from the loan officer's configured sender domain \u2014 treat as requiring confirmation. Supply either `quoteId` (for a saved quote) or inline `quoteData`. Free-tier accounts are limited to 2 sends per day; the tool returns the remaining daily quota so the assistant can inform the user. `calculatorType` must match the quote type. Returns delivery status and updated daily count.",
  inputSchema: {
    recipientEmail: z20.string().email().describe("Recipient email address."),
    recipientName: z20.string().optional().describe("Recipient display name."),
    calculatorType: z20.enum(["standard", "buydown", "earlyPayoff", "cashOutVsHeloc", "reverseMortgage"]),
    quoteId: z20.string().uuid().optional().describe("UUID of a saved quote to send. Use this OR quoteData."),
    quoteData: z20.record(z20.any()).optional().describe("Inline quote payload if not using quoteId."),
    confirm: z20.boolean().optional().describe("Must be `true` to actually send. Omit or set false to have the tool refuse and ask the user to confirm the recipient and content.")
  },
  annotations: { readOnlyHint: false, destructiveHint: true, idempotentHint: false, openWorldHint: true },
  handler: async (input, ctx) => {
    if (!ctx.isAuthenticated()) return notAuthed();
    const guard = requireConfirm(input.confirm, `send an email to ${input.recipientEmail}`);
    if (guard) return guard;
    const supabase = supabaseForUser(ctx);
    const { data: qty } = await supabase.rpc("get_daily_email_count", { p_user_id: ctx.getUserId() });
    const sentToday = typeof qty === "number" ? qty : 0;
    let payload = input.quoteData;
    if (!payload && input.quoteId) {
      const { data: q, error: error2 } = await supabase.from("saved_quotes").select("inputs, results, quote_name").eq("id", input.quoteId).maybeSingle();
      if (error2) return errorText(error2.message);
      if (!q) return errorText("Quote not found.");
      payload = { ...q.inputs, ...q.results, quoteName: q.quote_name };
    }
    if (!payload) return errorText("Provide either quoteId or quoteData.");
    const edgeType = input.calculatorType === "standard" ? "mortgage" : input.calculatorType === "buydown" ? "buydown" : input.calculatorType === "earlyPayoff" ? "early-payoff" : toDbCalcType(input.calculatorType);
    const { data, error } = await supabase.functions.invoke("send-quote-email", {
      body: {
        recipientEmail: input.recipientEmail,
        recipientName: input.recipientName,
        calculatorType: edgeType,
        quoteData: payload
      }
    });
    if (error) return errorText(error.message ?? "Email send failed.");
    return ok(`Email sent to ${input.recipientEmail}. Sent today: ${sentToday + 1}.`, {
      delivery: data,
      sentToday: sentToday + 1
    });
  }
});

